/**
 * Runs the desktop shell's Rust unit and integration tests through the real toolchain.
 *
 * The Tauri compile step is what makes this non-trivial: `tauri.conf.json`
 * lists bundle resources and `tauri::generate_context!` embeds the icon set
 * at compile time, and both are generated by `apps/desktop/scripts/prepare.mjs`
 * rather than committed (`resources/` proved it: with the directory absent the
 * build script failed with a bare "resource path `resources` doesn't exist",
 * and without the icons the compile stopped on a missing 32x32.png). An absent
 * prepared tree is this gate's honest UNRUN with the two setup commands named,
 * and a present one means cargo test runs the real Tauri build, including the
 * macOS process-level runtime-exit smoke.
 *
 * A settable side effect of this check is an empty `resources/` directory when
 * only icons are missing the other way around: the compile-time check needs the
 * path to exist, while the icons must be real files prepare generated.
 */
import { existsSync, mkdirSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join } from "node:path";

const root = join(import.meta.dirname, "..", "..");

const tauri = join(root, "apps", "desktop", "src-tauri");
const iconsReady = existsSync(join(tauri, "icons", "32x32.png"));

const cargo = spawnSync("cargo", ["--version"], { encoding: "utf8" });
if (cargo.error?.code === "ENOENT" || cargo.status !== 0) {
  console.log(
    "desktop-rust: UNRUN no cargo on PATH; rust inline tests not attempted",
  );
  process.exit(0);
}

if (!iconsReady) {
  console.log(
    "desktop-rust: UNRUN desktop icons are not prepared (tauri::generate_context embeds them at compile time)",
  );
  console.log("try: pnpm --dir apps/desktop install --ignore-workspace");
  console.log("then run: pnpm --dir apps/desktop run prepare:runtime");
  process.exit(0);
}

// The compile-time resources check needs the listed directory to exist even
// when the sidecar binary in it is absent from a tree that only runs tests.
mkdirSync(join(tauri, "resources"), { recursive: true });

const run = spawnSync("cargo", ["test"], {
  cwd: tauri,
  encoding: "utf8",
  timeout: Number(process.env.NOMO_CARGO_TIMEOUT_MS) || 900_000,
  killSignal: "SIGKILL",
});
const output = `${run.stdout ?? ""}${run.stderr ?? ""}`;
const timedOut = run.error?.code === "ETIMEDOUT";
if (timedOut) {
  console.log("desktop-rust: TIMEOUT cargo test exceeded its budget");
  console.log(
    output
      .split("\n")
      .filter((line) => /error|test result/.test(line))
      .slice(-12)
      .join("\n"),
  );
  process.exit(1);
}

const results = [...output.matchAll(/test result: (\w+)\. (\d+) passed/g)];
const passed = results.reduce((sum, match) => sum + Number(match[2]), 0);
const failedKinds = results.filter((match) => match[1] !== "ok").length;
const compileErrors = /error\[(E\d+)?\]|\nerror:/.test(output);

if (run.status !== 0 || failedKinds > 0 || compileErrors) {
  console.log(
    `desktop-rust: FAIL exit ${run.status ?? 1}, ${passed} passed, ${failedKinds} non-ok result lines`,
  );
  console.log(
    output
      .split("\n")
      .filter((line) => /^(error|test .* FAILED|failures:|.*panicked at)/.test(line.trim()))
      .slice(-24)
      .join("\n"),
  );
  process.exit(1);
}

console.log(`PASS: desktop-rust ${passed} rust tests passed`);
console.log(`desktop-rust: ${passed} rust tests passed`);
process.exit(0);
